def seed_existing_wallets(apps, schema_editor):
    User = apps.get_model(*settings.AUTH_USER_MODEL.split('.'))
    Wallet = apps.get_model('payments', 'Wallet')
    CreditLedger = apps.get_model('payments', 'CreditLedger')

    for user in User.objects.all().iterator():
        wallet, created = Wallet.objects.get_or_create(user_id=user.pk, defaults={'balance': 5000})
        if created:
            CreditLedger.objects.create(
                user_id=user.pk,
                delta=5000,
                reason='seed',
                ref_type='wallet',
            )


